import runpy, numpy as np
g = runpy.run_path('fit_dr_k51.py', run_name='diag')
rec, retained, ff, fx = g['rec'], g['retained'], g['fit_free'], g['fit_fixed_vmax']
def pts(c, src=None):
    p = sorted([(r['S'], r['v_scaled']) for s, r in retained.items() if r['cond']==c and (src is None or r['v_src'].startswith(src))])
    return np.array(p)
for c in ['C2','C3','C4','C7','C8']:
    p = pts(c); print(c, 'all free:', ['%.4f'%x for x in ff(p[:,0],p[:,1])], 'n=%d'%len(p))
for c, src in [('C2','D13'),('C2','D2'),('C2','D4'),('C2','D5/D12'),('C3','D2'),('C3','D9'),('C3','D15'),('C4','D13'),('C4','D9'),('C4','D4'),('C4','D5/D12')]:
    p = pts(c, src)
    if len(p) > 3:
        print(c, src, 'free vmax,km', ['%.4f'%x for x in ff(p[:,0],p[:,1])], 'n=%d'%len(p))
# rates at fixed S for C2,C3,C4,C7,C8 (scaled)
for S in [1,8,25,60,120]:
    row=[]
    for c in ['C2','C3','C4','C7','C8']:
        p=pts(c); m=[v for s,v in p if abs(s-S)<0.5]
        row.append('%s:%s'%(c, ','.join('%.3f'%x for x in m)))
    print('S=%s'%S, ' | '.join(row))

